use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use chrono::Utc;
use std::collections::BTreeMap;

const BILLING_UNIT_SECONDS: i64 = 15 * 60;
const MINIMUM_BILLABLE_SECONDS: i64 = 30 * 60;

pub struct InvoiceMonthlyCommand;

impl InvoiceMonthlyCommand {
    pub async fn execute<C: ApiClient>(
        api_client: C,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client
            .get_time_entries_filtered_minimal(since, until)
            .await?;
        print!("{}", format_monthly_invoice(&entries));
        Ok(())
    }
}

fn billable_seconds(entry: &TimeEntry) -> i64 {
    let duration = entry.duration.max(0);
    let rounded =
        ((duration + BILLING_UNIT_SECONDS - 1) / BILLING_UNIT_SECONDS) * BILLING_UNIT_SECONDS;
    rounded.max(MINIMUM_BILLABLE_SECONDS)
}

fn monthly_totals(entries: &[TimeEntry]) -> BTreeMap<String, i64> {
    let mut totals = BTreeMap::new();
    for entry in entries {
        if !entry.billable || entry.stop.is_none() || entry.duration < 0 {
            continue;
        }
        let month = entry.start.with_timezone(&Utc).format("%Y-%m").to_string();
        *totals.entry(month).or_insert(0) += billable_seconds(entry);
    }
    totals
}

fn format_monthly_invoice(entries: &[TimeEntry]) -> String {
    let totals = monthly_totals(entries);
    if totals.is_empty() {
        return "(no data)\n".to_string();
    }

    let mut output = String::new();
    let mut total = 0;
    for (month, seconds) in totals {
        output.push_str(&format!("{month}  {seconds}s\n"));
        total += seconds;
    }
    output.push_str(&format!("Total  {total}s\n"));
    output
}

